// scripts/build-content-plan.mjs
//
// Generates nagomi/data/content-plan.xlsx — the master content plan for
// Nagomi. Six sheets:
//
//   README           overview, mix targets, production flow
//   Contexts         real-life situations (Claude analysis, 2026-05-26)
//   Channels         functional modes of talk + target share
//   Relationships    who-is-talking-to-whom + typical register
//   Length Tiers     short → extended, with line ranges (floor: 5)
//   Conversations    every planned conversation (status: drafted | planned)
//
// Run with: node scripts/build-content-plan.mjs

import fs from 'node:fs';
import path from 'node:path';
import url from 'node:url';
import XLSX from 'xlsx';
import { EXTENSION_ROWS } from './content-plan-extension.mjs';

const __dirname  = path.dirname(url.fileURLToPath(import.meta.url));
const NAGOMI     = path.resolve(__dirname, '..');
const OUT_PATH   = path.join(NAGOMI, 'data', 'content-plan.xlsx');
fs.mkdirSync(path.dirname(OUT_PATH), { recursive: true });

const tierOf = (n) =>
  n <= 6  ? 'Short (5-6)'      :  // floor is 5
  n <= 12 ? 'Medium (7-12)'    :
  n <= 20 ? 'Long (13-20)'     :
            'Extended (21-30)';

// One row from positional fields; cleaner than 20-arg helpers.
// NOTE: `music` is dropped per the 2026-05-26 character/voice spec — no
// background music in the app. The `music` value in source data is ignored.
const row = (data, status) => {
  const [id, title, context, sub, ch1, ch2, rel, fml, A, Ag, B, Bg, lines, hook, setting, ambient, _music, iEn, iJp, iW] = data;
  const charC = ''; const charCGender = '';
  const speakerCount = [A, B, charC].filter(Boolean).length;
  return {
    id, title, context, sub_context: sub,
    primary_channel: ch1, secondary_channel: ch2,
    relationship: rel, formality: fml,
    char_A_name: A, char_A_gender: Ag,
    char_B_name: B, char_B_gender: Bg,
    char_C_name: charC, char_C_gender: charCGender,
    speaker_count: speakerCount,
    line_count_target: lines, length_tier: tierOf(lines),
    hook, purpose: '',
    ambient: ambient ?? '',
    setting,
    intro_en: iEn ?? '', intro_jp: iJp ?? '', intro_words: iW ?? '',
    status, notes: status === 'drafted' ? 'In src/data/conversations.js' : '',
  };
};

