const CONVERSATIONS = [
  ...DRAFTED_ROWS.map(r => row(r, 'drafted')),
  ...PLANNED_ROWS.map(r => row(r, 'planned')),
  ...EXTENSION_ROWS.map(r => row(r, 'planned')),
];

// ── Build workbook ──────────────────────────────────────────────────────────
const HEADER = [
  'id', 'title', 'context', 'sub_context',
  'primary_channel', 'secondary_channel',
  'relationship', 'formality',
  'char_A_name', 'char_A_gender',
  'char_B_name', 'char_B_gender',
  'char_C_name', 'char_C_gender',
  'speaker_count',
  'line_count_target', 'length_tier',
  'hook', 'purpose',
  'ambient',
  'setting',
  'intro_en', 'intro_jp', 'intro_words',
  'status', 'notes',
];

const wb = XLSX.utils.book_new();
const addSheet = (name, rows, cols) => {
  const ws = XLSX.utils.aoa_to_sheet(rows);
  if (cols) ws['!cols'] = cols;
  XLSX.utils.book_append_sheet(wb, ws, name);
};

addSheet('README',        README,        [{ wch: 95 }, { wch: 30 }]);
addSheet('Contexts',      CONTEXTS,      [{ wch: 22 }, { wch: 35 }, { wch: 22 }, { wch: 60 }]);
addSheet('Channels',      CHANNELS,      [{ wch: 22 }, { wch: 55 }, { wch: 30 }, { wch: 50 }, { wch: 40 }]);
addSheet('Relationships', RELATIONSHIPS, [{ wch: 28 }, { wch: 55 }, { wch: 28 }, { wch: 45 }]);
addSheet('Length Tiers',  LENGTH_TIERS,  [{ wch: 12 }, { wch: 8 }, { wch: 70 }, { wch: 50 }]);

const convRows = [HEADER, ...CONVERSATIONS.map(c => HEADER.map(k => c[k] ?? ''))];
const convCols = HEADER.map(k => {
  if (k === 'title' || k === 'setting' || k === 'intro_en' || k === 'intro_jp') return { wch: 60 };
  if (k === 'id') return { wch: 10 };
  if (k.endsWith('_gender')) return { wch: 8 };
  if (k === 'line_count_target' || k === 'speaker_count') return { wch: 6 };
  if (k === 'hook' || k === 'purpose' || k === 'notes' || k === 'intro_words' || k === 'ambient') return { wch: 30 };
  return { wch: 22 };
});
addSheet('Conversations', convRows, convCols);

XLSX.writeFile(wb, OUT_PATH);

// Also dump the conversations to JSON so the Python weaver can read them
// without an xlsx dep.
const planJsonPath = path.join(NAGOMI, 'data', 'plan-rows.json');
fs.writeFileSync(planJsonPath, JSON.stringify(CONVERSATIONS, null, 2), 'utf-8');

// ── Stats ───────────────────────────────────────────────────────────────────
const byTier = {};
const byContext = {};
const byPrimaryChannel = {};
const byStatus = {};
let emptyIntros = 0;
let emptyAmbient = 0;
for (const c of CONVERSATIONS) {
  byTier[c.length_tier] = (byTier[c.length_tier] ?? 0) + 1;
  byContext[c.context] = (byContext[c.context] ?? 0) + 1;
  byPrimaryChannel[c.primary_channel] = (byPrimaryChannel[c.primary_channel] ?? 0) + 1;
  byStatus[c.status] = (byStatus[c.status] ?? 0) + 1;
  if (!c.intro_en || !c.intro_jp) emptyIntros++;
  if (!c.ambient) emptyAmbient++;
}

console.log(`wrote ${OUT_PATH}`);
console.log(`  ${CONVERSATIONS.length} conversations`);
console.log(`  by status:`, byStatus);
console.log(`  by tier:`, byTier);
console.log(`  by context:`, byContext);
console.log(`  by primary channel:`, byPrimaryChannel);
console.log(`  rows missing intro_en or intro_jp:`, emptyIntros);
console.log(`  rows with empty ambient (phone calls etc):`, emptyAmbient);
